  Lemma ainv_frame_driver : forall A M M' vm,
    ainv A M vm -> alloc_top vm = (bv_unsigned sp0 - 8388608)%Z ->
    (forall a : word, M' a <> M a ->
       (bv_unsigned sp0 - 8388608 <= bv_unsigned a < bv_unsigned sp0)%Z \/ (0x10000 <= bv_unsigned a < 0x69b38)%Z
       \/ (exists p n, live A p = Some n /\ (bv_unsigned p <= bv_unsigned a < bv_unsigned p + n)%Z)) ->
    mem_grows M M' ->
    (forall a : word, (0x6b000 <= bv_unsigned a < bv_unsigned sp0 - 8388608)%Z \/ (0x1000 <= bv_unsigned a < 0x10000)%Z ->
                      M' a <> None -> M a <> None) ->
    ainv A M' vm.
